+/** A parsed trigger. */
+export type Trigger =
+	| { readonly on: 'load' }
+	| { readonly on: 'idle' }
+	| { readonly on: 'visible' }
+	| { readonly on: 'interaction' }
+	| { readonly on: 'media'; readonly query: string };
